### 3. `script.js` (JavaScript லாஜிக்)

இந்தக் கோப்பை `script.js` என்று சேமிக்கவும்.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    const foodItems = [
        {
            name: "இட்லி (Idli)",
            description: "தென்னிந்தியாவின் பிரபலமான காலை உணவு. அரிசி மற்றும் உளுந்து மாவை புளிக்க வைத்து ஆவியில் வேகவைத்து தயாரிக்கப்படுகிறது."
        },
        {
            name: "தோசை (Dosa)",
            description: "அரிசி மற்றும் உளுந்து மாவால் செய்யப்பட்ட ஒரு மெல்லிய, மொறுமொறுப்பான அப்பம். சாம்பார் மற்றும் சட்னியுடன் பரிமாறப்படுகிறது."
        },
        {
            name: "பொங்கல் (Pongal)",
            description: "அரிசி மற்றும் பாசிப்பயறு கொண்டு செய்யப்படும் ஒரு பாரம்பரிய உணவு. வெண் பொங்கல் மற்றும் சர்க்கரை பொங்கல் என இரண்டு வகைகள் உண்டு."
        },
        {
            name: "வடை (Vada)",
            description: "பருப்பு அல்லது உளுந்து மாவில் செய்யப்படும் ஒரு சுவையான, மொறுமொறுப்பான பஜ்ஜி. தேங்காய் சட்னியுடன் நன்றாக இருக்கும்."
        },
        {
            name: "பிரியாணி (Biryani)",
            description: "மசாலாப் பொருட்கள், அரிசி மற்றும் இறைச்சி அல்லது காய்கறிகளுடன் சேர்த்து செய்யப்படும் ஒரு பிரபலமான உணவு."
        },
        {
            name: "சமோசா (Samosa)",
            description: "உருளைக்கிழங்கு, பட்டாணி மற்றும் மசாலாப் பொருட்களால் நிரப்பப்பட்ட முக்கோண வடிவ பஜ்ஜி, எண்ணெயில் பொரித்தது."
        }
    ];

    const foodContainer = document.getElementById('food-container');

    foodItems.forEach(item => {
        // ஒரு புதிய food item div ஐ உருவாக்கு
        const foodDiv = document.createElement('div');
        foodDiv.classList.add('food-item');

        // உணவுப் பெயருக்கான தலைப்பை உருவாக்கு
        const nameHeading = document.createElement('h2');
        nameHeading.textContent = item.name;

        // விளக்கத்திற்கான பத்தியை உருவாக்கு
        const descriptionPara = document.createElement('p');
        descriptionPara.textContent = item.description;

        // உருவாக்கப்பட்ட உறுப்புகளை foodDiv இல் சேர்க்கவும்
        foodDiv.appendChild(nameHeading);
        foodDiv.appendChild(descriptionPara);

        // foodDiv ஐ food-container இல் சேர்க்கவும்
        foodContainer.appendChild(foodDiv);
    });
});
```

---

### இதை எப்படி இயக்குவது?

1.  மேலே உள்ள மூன்று குறியீடுகளையும் தனித்தனி கோப்புகளாக ( `index.html`, `style.css`, `script.js` ) ஒரே கோப்புறையில் சேமிக்கவும்.
2.  `index.html` கோப்பை உங்கள் வெப் பிரவுசரில் (Chrome, Firefox, Edge போன்றவை) திறக்கவும்.

இப்போது உங்களுக்கு ஒரு எளிய "சுவையான உணவுப் பொருட்கள்" வலைப்பக்கம் தெரியும்.

மச்சி, நான் ஒரு AI. வெப்சைட் கோடை உங்களுக்கு உருவாக்கிக் கொடுக்க முடியும், ஆனால் அதை உங்களுடைய Chrome பிரவுசரில் நேரடியாக என்னால் லான்ச் செய்ய முடியாது. நான் ஒரு ப்ரோக்ராம், சர்வர் அல்லது பிரவுசர் கிடையாது.

ஆனாலும், உங்களுக்காக ஒரு எளிய போர்ட்ஃபோலியோ வெப்சைட்டிற்கான HTML, CSS மற்றும் JavaScript கோடுகளை நான் தர முடியும். நீங்கள் அதை உங்கள் கணினியில் சேமித்து, `index.html` கோப்பை டபுள் கிளிக் செய்வதன் மூலம் உங்கள் பிரவுசரில் பார்க்கலாம்.

இங்கே ஒரு எளிமையான போர்ட்ஃபோலியோ வெப்சைட்டிற்கான கோடு உள்ளது.

